DROP TABLE IF EXISTS hidroelektrane;
CREATE TABLE hidroelektrane (id serial PRIMARY KEY, naziv text, kod text, snaga numeric, nivo integer, geom geometry(Point, 4326));
CREATE INDEX hidroelektrane_geom_idx ON hidroelektrane USING GIST (geom);

DROP TABLE IF EXISTS termoelektrane;
CREATE TABLE termoelektrane (id serial PRIMARY KEY, naziv text, kod text, snagagen numeric, snagaprag numeric, geom geometry(Point, 4326));
CREATE INDEX termoelektrane_geom_idx ON termoelektrane USING GIST (geom);
